export const DEFAULT_DEFENDER_EMBLEM: DefenderEmblemId = "shield-knot";
export const DEFENDER_EMBLEM_KEY = "brandubh.defenderEmblem";

const IDS = new Set<string>(DEFENDER_EMBLEMS.map((e) => e.id));
export function isDefenderEmblemId(v: unknown): v is DefenderEmblemId {
  return typeof v === "string" && IDS.has(v);
}
export function defenderEmblemById(id: DefenderEmblemId): DefenderEmblemDef {
  return DEFENDER_EMBLEMS.find((e) => e.id === id) ?? DEFENDER_EMBLEMS[0];
}
export function loadDefenderEmblem(): DefenderEmblemId {
  try {
    const s = localStorage.getItem(DEFENDER_EMBLEM_KEY);
    if (isDefenderEmblemId(s)) return s;
  } catch {
    /* ignore */
  }
  return DEFAULT_DEFENDER_EMBLEM;
}
